import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d as m,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"FX 波动率报价 ATM / RR / BF","description":"","frontmatter":{"title":"FX 波动率报价 ATM / RR / BF","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fx-vol-quotes.md","filePath":"quant/fx-vol-quotes.md","lastUpdated":1789023840000}'),d={name:"quant/fx-vol-quotes.md"};function u(B,a,c,A,_,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="fx-波动率报价-atm-rr-bf" tabindex="-1">FX 波动率报价 ATM / RR / BF <a class="header-anchor" href="#fx-波动率报价-atm-rr-bf" aria-label="Permalink to &quot;FX 波动率报价 ATM / RR / BF&quot;">​</a></h1><div class="epigraph"><p>外汇微笑不按执行价报，而按 ATM、风险反转与蝶式三个可交易结构报；它们近似水平、倾斜与弯曲。</p><footer>—— Malz, Estimating the Probability Distribution of the Future Exchange Rate from Option Prices, Journal of Derivatives, 1997；Clark, Foreign Exchange Option Pricing</footer></div><p><a href="/quant/garman-kohlhagen">上一课</a>给出无微笑的 GK。本课把 <a href="/quant/quoting-conventions">报价惯例</a> 在 FX 上展开：ATM vol、25Δ risk reversal、25Δ butterfly。缺口是这三件事如何还原出 \\(K\\mapsto\\sigma(K)\\)，以及 Vanna–Volga 一类快捷法与完整曲面校准的分工。后课 FX 障碍依赖翼部，不能只盯 ATM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>做市商报 \\(\\sigma_{\\mathrm{ATM}}\\)、\\(\\mathrm{RR}_{25}=\\sigma_{25c}-\\sigma_{25p}\\)、\\(\\mathrm{BF}_{25}=\\tfrac12(\\sigma_{25c}+\\sigma_{25p})-\\sigma_{\\mathrm{ATM}}\\)（定义有变体）。三个数交易的是三个流动性最好的组合，不是三个独立执行价。问题是反解 \\(\\sigma_{25c},\\sigma_{25p}\\) 再插值整张微笑：Delta 与 \\(K\\) 的映射依赖 vol 自身，方程是隐式的，要迭代。用股权那套「按 \\(K\\) 扫隐波」去读 FX 经纪人屏幕，会对不上任何一笔成交。</p><p>Malz 用 RR/BF 近似风险中性密度的偏度与峰度。快捷，但不是无套利曲面。生产仍应映到内部 \\((K,\\sigma)\\) 再做无套利检查。</p><h3 id="vanna–volga-是快捷-不是模型" tabindex="-1">Vanna–Volga 是快捷，不是模型 <a class="header-anchor" href="#vanna–volga-是快捷-不是模型" aria-label="Permalink to &quot;Vanna–Volga 是快捷，不是模型&quot;">​</a></h3><p>用 ATM、RR、BF 三笔的市场价格去配三个权重，修正 GK 价格的 Vanna 与 Volga 项，得到一阶微笑调整。对香草好用，对障碍与触碰会漏掉触碰概率对翼部的依赖。后课障碍不要只用 Vanna–Volga 当官方模型；它是报价核对。</p><p><span class="marginnote">10Δ 的 RR/BF 流动性差、噪声大，却决定触碰价格。校准若只配 25Δ，应对 10Δ 加正则或单独限额。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Adapter：报价三元组 → 迭代求解对应 \\(K\\) 与 \\(\\sigma\\) → 用 SABR 或三次样条在 Delta 或 \\(K\\) 空间插值 → 输出内部曲面。日间 bump 应 bump ATM/RR/BF 再映射，这样桶与经纪人结构一致，见 <a href="/quant/vega-buckets">Vega 桶</a>。对冲：用 ATM 跨式、RR 结构、BF 结构去减三因子，而不是买一堆零散 Delta。</p><p>期限结构：每个到期一套三元组，远期微笑由动态模型负责，不要在每个到期独立插值后再假装无日历套利。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ATM/RR/BF 是市场选择的主成分交易方式。PCA 课里的水平、倾斜、弯曲在 FX 上几乎被直接上市。因此 FX 簿的风险报告天然是三因子加翼部残差。把它们拆成许多 \\(K\\) 再独立 bump，会破坏做市商实际能成交的方向。</p>',14)),(e(),s(h,null,{default:r(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ATM%5B%22ATM%20vol%20%E6%B0%B4%E5%B9%B3%22%5D%20--%3E%20Trip%5B%22%E4%B8%89%E5%85%83%E7%BB%84%22%5D%0A%20%20RR%5B%22RR%20%E5%80%BE%E6%96%9C%22%5D%20--%3E%20Trip%0A%20%20BF%5B%22BF%20%E5%BC%AF%E6%9B%B2%22%5D%20--%3E%20Trip%0A%20%20Trip%20--%3E%20Impl%5B%22%E8%BF%AD%E4%BB%A3%20Delta%20%E5%88%B0%20K%22%5D%0A%20%20Impl%20--%3E%20Surf%5B%22%E5%86%85%E9%83%A8%E5%BE%AE%E7%AC%91%22%5D%0A%20%20Surf%20--%3E%20VV%5B%22Vanna-Volga%20%E5%BF%AB%E6%8D%B7%E6%A0%B8%E5%AF%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定义变体（包括/不包括 ATM 的 BF、Delta 是否 premium-adjusted）在确认书里，代码必须按对手切换。新兴市场只报 ATM 与 RR、没有 BF，弯曲来自先验。跳与 fix 事件（非农、央行）让短到期微笑的 BF 爆炸，三因子不够，应加事件情景。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FX 微笑的市场坐标是 ATM、RR、BF，不是执行价网格。</li><li>Delta 与 \\(K\\) 互相依赖，必须迭代；对冲用这三种结构。</li><li>Vanna–Volga 适合香草核对，不适合当障碍官方模型。</li><li>出处：Malz, <em>Journal of Derivatives</em>, 1997；Clark, <em>Foreign Exchange Option Pricing</em>。</li></ul>',4))])}const E=o(d,[["render",u]]);export{T as __pageData,E as default};
